const fs = require('fs');

function main() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const n = readInt();
    if (n === null) return;

    const head = new Int32Array(n + 1).fill(-1);
    // A soma dos M_i é no máximo 600.000
    const maxEdges = 600005;
    const to = new Int32Array(maxEdges);
    const next = new Int32Array(maxEdges);
    let edgeCount = 0;

    for (let i = 1; i <= n; i++) {
        const m = readInt();
        for (let j = 0; j < m; j++) {
            const v = readInt();
            to[edgeCount] = v;
            next[edgeCount] = head[i];
            head[i] = edgeCount++;
        }
    }

    // team: 0 = unvisited, 1 = time 1, 2 = time 2
    const team = new Uint8Array(n + 1);
    const queue = new Int32Array(n + 1);
    let qHead = 0;
    let qTail = 0;

    // Aluno 1 sempre no time 1
    team[1] = 1;
    queue[qTail++] = 1;

    // BFS
    while (qHead < qTail) {
        const u = queue[qHead++];
        const currentTeam = team[u];
        const nextTeam = currentTeam === 1 ? 2 : 1;

        let e = head[u];
        while (e !== -1) {
            const v = to[e];
            if (team[v] === 0) {
                team[v] = nextTeam;
                queue[qTail++] = v;
            }
            e = next[e];
        }
    }

    // Se o grafo não for totalmente conexo (embora o problema garanta solução única),
    // qualquer componente não visitado pode ser visitado da mesma forma.
    for (let i = 1; i <= n; i++) {
        if (team[i] === 0) {
            team[i] = 1;
            queue[qTail++] = i;
            while (qHead < qTail) {
                const u = queue[qHead++];
                const currentTeam = team[u];
                const nextTeam = currentTeam === 1 ? 2 : 1;

                let e = head[u];
                while (e !== -1) {
                    const v = to[e];
                    if (team[v] === 0) {
                        team[v] = nextTeam;
                        queue[qTail++] = v;
                    }
                    e = next[e];
                }
            }
        }
    }

    const team1 = [];
    const team2 = [];

    for (let i = 1; i <= n; i++) {
        if (team[i] === 1) {
            team1.push(i);
        } else {
            team2.push(i);
        }
    }

    process.stdout.write(team1.join(' ') + '\n' + team2.join(' ') + '\n');
}

main();
